import { Icon } from '../Icon'

/** Small "AI" marker so users know a result was generated by AI. */
export function AiLabel() {
  return (
    <span className="inline-flex items-center gap-1 rounded-md bg-violet-50 px-1.5 py-0.5 text-[11px] font-semibold text-violet-700 ring-1 ring-violet-200 ring-inset dark:bg-violet-500/10 dark:text-violet-300 dark:ring-violet-500/30">
      <Icon name="sparkles" className="h-3 w-3" />
      AI
    </span>
  )
}
